INSERT INTO `product` VALUES (1,'Sinandomeng Special','Premium White','Local','Sinandomeng','All-time favorite Filipino staple with long white grains, soft texture when cooked, and great volume.',2150.00,1075.00,48.00,245.00,485.00,960.00,50.00,'Active'),(2,'Dinorado Fancy Special','Aromatic','Local','Dinorado','Naturally aromatic local pinkish rice known for its sweet scent and sticky, soft grain texture.',2450.00,1225.00,55.00,275.00,545.00,1080.00,50.00,'Active'),(3,'Jasmine Fragrant Premium','Fragrant Import','Imported','Jasmine','Top-grade imported whole grain fragrant rice with silky smooth texture and fragrant floral aroma.',2800.00,1400.00,62.00,310.00,615.00,1220.00,50.00,'Active'),(4,'Angelika White Rice','Regular Milled','Local','Angelika','Affordable, high-yield white rice favored by carinderias and local food businesses for its firm texture.',1950.00,975.00,44.00,220.00,435.00,860.00,50.00,'Active'),(5,'Malagkit Glutinous Rice','Specialty Rice','Local','Glutinous / Malagkit','Pure sticky glutinous rice essential for traditional kakanin, champorado, biko, and holiday dishes.',3100.00,1550.00,70.00,350.00,690.00,1370.00,50.00,'Active'),(6,'IR-64 Well-Milled Rice','Standard Local','Local','Well-Milled (IR-64)','Standard commercial well-milled rice offering excellent value, uniform grain length, and everyday reliability.',1850.00,925.00,42.00,210.00,415.00,820.00,50.00,'Active'),(7,'Milagrosa Super Fragrant','Aromatic','Local','Milagrosa','Heritage Philippine aromatic rice variety with slender grains, pleasant fragrance, and tender mouthfeel.',2600.00,1300.00,58.00,290.00,575.00,1140.00,50.00,'Active'),(8,'Coco Pandan Premium Aromatic','Fragrant Import','Imported','Coco Pandan','Imported aromatic rice infused with sweet pandan aroma, soft chewing texture, and pure white grains.',2700.00,1350.00,60.00,300.00,595.00,1180.00,50.00,'Active'),(9,'Brown Rice Organic Whole Grain','Healthy Specialty','Local','Brown Rice','Unpolished whole grain brown rice rich in dietary fiber, nutrients, and low glycemic index for health conscious buyers.',3300.00,1650.00,75.00,370.00,730.00,1450.00,50.00,'Active'),(10,'Japanese Calrose Rice','Specialty Rice','Imported','Calrose','Authentic medium grain sushi-grade rice with balanced moisture retention and tender, clinging grains.',3400.00,1700.00,78.00,380.00,755.00,1500.00,50.00,'Active'),(11,'Maharlika Premium Long Grain','Premium White','Local','Maharlika','Premium milled long grain local rice that cooks into fluffy, separate, non-sticky fragrant grains.',2250.00,1125.00,51.00,255.00,500.00,990.00,50.00,'Active'),(12,'Super Angelica Supreme','Premium White','Local','Angelica','Extra well-milled supreme Angelica rice featuring clean white kernels, soft fluffiness, and versatile cooking quality.',2050.00,1025.00,46.00,230.00,455.00,900.00,50.00,'Active');
